UPDATE forum_questions
SET title = #{title}, content = #{content}, user_id = #{userId},
    answer_count = #{answerCount}, favorite_count = #{favoriteCount},
    follow_count = #{followCount}, view_count = #{viewCount},
    is_resolved = #{isResolved}, status = #{status}, updated_at = #{updatedAt}
WHERE id = #{id}
